// clang-format on

struct ControlSkin
{
    std::string_view id;
    KnobSkin knob;
    ControlText label;
    ControlText value;
    SwitchSkin switchOff;
    SwitchSkin switchOn;
    TabSkin tabs;
    ControlBox group;
    ControlText groupTitle;
    ControlBox shell;
    ControlBox section;
    ControlBox art;
    /// A plot's card (.eq-visualizer: the EQ curve, a cabinet's or pickup's response): its box and
    /// padding, the title and range over the plot, and the plot's own well.
    ControlBox card;
    float cardPadding;
    ControlText cardTitle;
    ControlText cardRange;
    ControlBox plot;
    /// The page's text (the body's face, weight and size), an effect's title, and how much
    /// larger than its size a title is drawn (its font-size-adjust over its face's x-height).
    ControlText body;
    ControlText title;
    float titleScale;
    /// Cheeks either side of the effect's panel, outside it (0 wide for none), their outer
    /// corners rounded; their backgrounds are backdrops.cheekLeft and cheekRight.
    float cheekWidth;
    float cheekRadius;
    /// The level meters as a needle gauge (Studio 1973's VU meters): the face picture, under the
    /// UI's assets, and its size; no picture for the web UI's ladder of segments. The needle's
    /// geometry is the face's (tools/studio-1973-theme-assets/vu-face.mjs).
    std::string_view gaugeFace;
    float gaugeWidth;
    float gaugeHeight;
    KeySkins keys;
    NodeSkins nodes;
    DisplaySkin presetDisplay;
    DisplaySkin tempo;
    /// The backgrounds of the bars, the page, the effect's panel and a dialog.
    Backdrops backdrops;
};

